INSERT INTO `prompts` (`id`, `slug`, `title`, `content`, `description`, `search_text`, `source_url`, `source_author`, `status`, `author_id`, `view_count`, `like_count`, `collect_count`, `copy_count`, `created_at`, `updated_at`, `published_at`)
VALUES
  ('prompt_evolink_ecommerce_113', 'evolink-ecommerce-113-e-commerce-main-image-luxury-amber-perfume-ad', 'E-commerce Main Image - Luxury Amber Perfume Ad', 'A luxurious cinematic product photograph of a classic rectangular perfume bottle inspired by {argument name="brand label" default="N°5 CHANEL PARIS PARFUM"}, placed upright on a glossy black marble surface with white veining. The bottle is centered slightly to the right, made of clear faceted glass with a large transparent crystal stopper, filled with rich amber-gold perfume that glows from within. Tiny condensation droplets cover the glass, adding texture and realism. Dramatic warm lighting from the upper left creates golden highlights, deep reflections on the marble, and a soft luminous bloom in the background. Wisps of elegant smoke curl around the bottle on both sides, enhancing a moody high-end advertisement feel. Dark background, shallow depth of field, ultra-detailed studio product photography, luxury beauty campaign aesthetic, crisp focus on the bottle, realistic reflections, warm black-and-gold color palette. Add a small white {argument name="corner logo" default="Pollo.ai"} in the top-right corner. Square composition, premium commercial ad, photorealistic, high contrast, refined and sophisticated.', '电商产品、商业摄影和商品广告主视觉。来自 EvoLinkAI GPT-Image-2 案例库。', 'E-commerce Main Image - Luxury Amber Perfume Ad 电商产品、商业摄影和商品广告主视觉。来自 EvoLinkAI GPT-Image-2 案例库。 电商产品图 A luxurious cinematic product photograph of a classic rectangular perfume bottle inspired by {argument name="brand label" default="N°5 CHANEL PARIS PARFUM"}, placed upright on a glossy black marble surface with white veining. The bottle is centered slightly to the right, made of clear faceted glass with a large transparent crystal stopper, filled with rich amber-gold perfume that glows from within. Tiny condensation droplets cover the glass, adding texture and realism. Dramatic warm lighting from the upper left creates golden highlights, deep reflections on the marble, and a soft luminous bloom in the background. Wisps of elegant smoke curl around the bottle on both sides, enhancing a moody high-end advertisement feel. Dark background, shallow depth of field, ultra-detailed studio product photography, luxury beauty campaign aesthetic, crisp focus on the bottle, realistic reflections, warm black-and-gold color palette. Add a small white {argument name="corner logo" default="Pollo.ai"} in the top-right corner. Square composition, premium commercial ad, photorealistic, high contrast, refined and sophisticated. @Polanco_IA EvoLinkAI GPT-Image 2 NanoBanan tag_ai_image tag_evolink tag_ecommerce tag_product_photo tag_marketing tag_poster tag_portrait tag_logo', 'https://x.com/Polanco_IA/status/2047689647967609037', '@Polanco_IA', 'published', NULL, 11946, 1264, 637, 2628, cast(unixepoch('subsecond') * 1000 as integer), cast(unixepoch('subsecond') * 1000 as integer), cast(unixepoch('subsecond') * 1000 as integer));
