  ('prompt_evolink_ui_112', 'evolink-ui-112-cloud-shape-doodle-generation', 'Cloud shape doodle generation', 'Based on the shape of the {argument name="subject" default="clouds"} in the image, identify what object, animal, or person they most resemble. Do not change the original image; instead, draw that object, animal, or person over the original image in a {argument name="art style" default="doodle"} style.', 'UI mockup、社媒卡片、信息图和界面概念。来自 EvoLinkAI GPT-Image-2 案例库。', 'Cloud shape doodle generation UI mockup、社媒卡片、信息图和界面概念。来自 EvoLinkAI GPT-Image-2 案例库。 UI 与社媒 Based on the shape of the {argument name="subject" default="clouds"} in the image, identify what object, animal, or person they most resemble. Do not change the original image; instead, draw that object, animal, or person over the original image in a {argument name="art style" default="doodle"} style. @Gorden_Sun EvoLinkAI GPT-Image 2 NanoBanan tag_ai_image tag_evolink tag_ui tag_design tag_mockup', 'https://x.com/Gorden_Sun/status/2048080137149899133', '@Gorden_Sun', 'published', NULL, 4998, 492, 251, 1084, cast(unixepoch('subsecond') * 1000 as integer), cast(unixepoch('subsecond') * 1000 as integer), cast(unixepoch('subsecond') * 1000 as integer));
INSERT INTO `prompts` (`id`, `slug`, `title`, `content`, `description`, `search_text`, `source_url`, `source_author`, `status`, `author_id`, `view_count`, `like_count`, `collect_count`, `copy_count`, `created_at`, `updated_at`, `published_at`)
