  ('prompt_youm_48', 'youmind-48-infographic-edu-visual-caloryx-nutrition-app-prototype-board', 'Infographic / Edu Visual - Caloryx Nutrition App Prototype Board', '{"type":"mobile app prototype presentation board for a nutrition and food scanner app","overall_style":"clean modern iOS UI mockup, white background, rounded cards, soft shadows, green health-tech accent color, Poppins-style typography, realistic phone screenshots arranged in a horizontal product-design showcase","app":{"name":"{argument name=\"app name\" default=\"Caloryx\"}","language":"Spanish","concept":"AI-powered meal scanning, calorie tracking, nutritional analysis, healthier alternatives, and progress dashboard"},"layout":{"canvas":"wide landscape presentation sheet with five large iPhone mockups across the top row and brand-system components across the bottom row","top_row":{"count":5,"screens":[{"title":"MENÚ","position":"far left","description":"slide-out side navigation drawer with profile greeting, blurred app screen behind it, and a vertical list of navigation actions","visible_text":["Hola, Laura! 👋","Tu viaje saludable","Inicio","Panel principal","Análisis","Historial y resultados","Metas","Objetivos y progreso","Tendencias","Estadísticas","Ajustes","Preferencias","Ayuda","Soporte y tutoriales","Caloryx PRO","Desbloquea todas las funciones","Cerrar sesión"],"counted_items":{"navigation_items_count":7,"navigation_items":["Inicio","Análisis","Metas","Tendencias","Ajustes","Ayuda","Cerrar sesión"],"promotional_cards_count":1,"promotional_cards":["Caloryx PRO"]}},{"title":"HOME (NUEVO)","position":"left center","description":"home dashboard showing the user greeting, today''s calorie summary, macro cards, food analysis call-to-action, recent meal card, and bottom tab bar","visible_text":["Caloryx","PRO","¡Bienvenida, Laura! 🌿","Estás haciendo un gran trabajo","Tu resumen de hoy","700 / 2,777 kcal","Resta de tu meta diaria","Proteínas","Carbohidratos","Grasas","Analiza tu comida","Escanea o sube una foto para obtener información nutricional instantánea.","Escanear comida","Galería","Tomar foto","Comidas recientes","Hamburguesa","700 kcal","Inicio","Análisis","Metas","Perfil"],"counted_items":{"macro_cards_count":3,"macro_cards":["Proteínas","Carbohidratos","Grasas"],"primary_actions_count":3,"primary_actions":["Escanear comida","Galería","Tomar foto"],"bottom_tabs_count":4,"bottom_tabs":["Inicio","Análisis","Metas","Perfil"]}},{"title":"ESCÁNER DE COMIDA (NUEVO)","position":"center","description":"camera scanner interface pointed at a Burger King meal with a burger, fries, and drink, using green corner scan brackets, a bottom progress bar, close button, flash button, and dark camera overlay","visible_text":["Detectando alimentos...","Analizando nutrientes con IA"],"food_subject":"{argument name=\"scanned food\" default=\"Burger King meal with Whopper burger, fries, and soda cup\"}","counted_items":{"camera_controls_count":2,"camera_controls":["close button","flash button"],"detected_food_items_visible_count":3,"detected_food_items_visible":["burger","fries","soda cup"]}},{"title":"RESULTADO DEL ANÁLISIS (MEJORADO)","position":"right center","description":"analysis results screen with food photo header, back button, PRO badge, health score card, nutrition summary, detected foods list, and green save button","visible_text":["PRO","Saludabilidad de esta comida","1.6","Resumen nutricional","1,735 kcal","Proteínas","Carbohidratos","Grasas","Azúcares","Alimentos detectados","3 elementos","Burger King Whopper","670 kcal","Burger King Chicken Sandwich","500 kcal","Burger King French Fries","400 kcal","Guardar comida"],"counted_items":{"detected_foods_count":3,"detected_foods":["Burger King Whopper","Burger King Chicken Sandwich","Burger King French Fries"],"nutrition_metrics_count":5,"nutrition_metrics":["1,735 kcal","Proteínas 59g","Carbohidratos 181g","Grasas 88g","Azúcares 58g"]}},{"title":"DETALLE DEL ALIMENTO","position":"far right","description":"individua