INSERT INTO `prompts` (`id`, `slug`, `title`, `content`, `description`, `search_text`, `source_url`, `source_author`, `status`, `author_id`, `view_count`, `like_count`, `collect_count`, `copy_count`, `created_at`, `updated_at`, `published_at`)
VALUES
  ('prompt_youm_49', 'youmind-49-infographic-edu-visual-ai-ad-and-infographic-capability-collage', 'Infographic / Edu Visual - AI Ad and Infographic Capability Collage', '{"type":"dense comparison collage of AI-generated commercial prompt-adherence examples","format":"single 3x3 social media showcase grid, 16:9 aspect ratio, no gutters or thin seams between panels, high-detail realistic and graphic mixed media","overall_style":"A busy viral tech-demo collage showing that one image model can generate Chinese ads, livestream shopping layouts, English infographics, game UI, food recipe posters, product photography, and handwritten mail. Preserve readable typography where possible, mixing Chinese and English text, with realistic lighting, ecommerce overlays, icons, badges, and small UI details.","layout":{"count":9,"arrangement":"three rows by three columns, with the center and right panels tightly cropped like a screenshot mosaic","panels":[{"position":"top left","type":"Chinese tea product beautification ad","visible_text_count":8,"texts":["国风产品也能用AI修出高级感","茶叶、礼盒、伴手礼都能套用","Before","After","教程干货","#AI修图","#国风品牌","#产品美化","#电商教程"],"description":"Traditional Chinese tea still-life with cylindrical green tea tins, loose tea leaves, ceramic cups, wooden table, warm dark studio lighting; a Before/After split shows the same tea product transformed into an elegant ink-wash landscape background with bamboo and mountains."},{"position":"top center","type":"Chinese livestream flash sale screenshot","visible_text_count":13,"texts":["LIVE","12.8万人","88.6K","FLASH SALE","闪购!","时光焕亮修护精华液","¥199","¥399","仅剩12件","分享","送礼","立即抢购","VIP"],"description":"A female beauty influencer with blurred face holds a cosmetic serum bottle and points upward, surrounded by livestream hearts, viewer counters, chat bubbles, red sale badge, price card, and mobile shopping interface elements."},{"position":"top right","type":"decorative English wellbeing infographic","visible_text_count":7,"texts":["Habits for Emotional Wellbeing","Practice Mindfulness","Be present, observe without judging, accept without resisting","Continuous Learning","Cultivate Gratitude","Regular Physical Activity","Stay Connected","Prioritize Sleep"],"description":"Cream parchment-style infographic with navy blue and gold botanical ornaments, symmetrical leaves, small line icons, curved dividers, and serif typography about mental health habits."},{"position":"bottom left","type":"Chinese kitchen appliance ecommerce poster","visible_text_count":13,"texts":["森火 SENFO","森焙嵌入式蒸烤箱","把星级餐桌搬回家","蒸 | 烤 | 空气炸 | 发酵 | 炖煮 五合一","70L大容量","上下独立控温","智能菜单","一键清洁","¥5699","前200名","赠豪华烘焙套装","限时钜惠","马上升级厨房"],"description":"Modern minimalist kitchen interior with built-in black glass oven, island counter, sea-view window, vertical white feature-card sidebar with appliance icons and pricing."},{"position":"bottom center left","type":"Chinese spicy pork recipe poster","visible_text_count":10,"texts":["辣椒炒肉","越简单越考验火候","家庭灶也能炒出餐馆效果","食材:","五花肉 260g","二荆条 120g","薄皮青椒 100g","独蒜 1头","Step 1 切肉","Step 2 腌制","Step 3 干煸辣椒","Step 4 猪肉入锅","Step 5 蒜末、辣椒回锅","锅气是灵魂"],"description":"Dark smoky food poster with a wok or black pan full of glossy pork belly slices and green chilies, steam rising, bold Chinese headline and numbered cooking steps with small ingredient icons."},{"position":"bottom center","type":"fantasy mobile game gacha UI screenshot","visible_text_count":15,"texts":["BLIND BOX","COLLECTION","WISH LIST","EVENT","RANKING","Stella","Open 1 Box","Open 10 Boxes","NEW Starfall Series","Rate UP!","Collect Reward","45/100","HOME","SHOP","ADVENTURE","FRIENDS","MISSIONS"],"description":"Colorful purple-blue mobile game interface with a cute chibi cat-eared magical girl named Stella in the middle, bubbles, stars, currency counters across the top, side menu buttons, reward banners, and bottom navigation."},{"position":"bottom center right","type":"handwritten postcard and envelope","visible_text_count":8,"texts":["Dear Emily,","Paris is as lovely as we dreamed, with charming little bakeries and cafés lining every street. Yesterday, we visited the Louvre and spent hours marveling at the paintings. Missing you greatly and hoping you can join me here one day soon. Warmest wishes, Clara","PLACE STAMP HERE","Miss Emily Carter","28 Rosewood Avenue","Bath","Somerset","BA2 3JV","England"],"description":"Vintage beige postcard on wooden table, left side filled with cursive handwritten letter, right side with address lines, stamp placeholder, faint postal marks, warm nostalgic lighting."},{"position":"bottom right center","type":"gaming hydration drink ad","visible_text_count":11,"texts":["QUEUE UP.","POWER ON.","GAMING HYDRATION DRINK","ZERO CRASH FORMULA","Caffeine + electrolytes + B12, crafted for ranked nights and tournament weekends.","LEVEL UP YOUR FOCUS","CLEAN ENERGY","ELECTROLYTE HYDRATION","B12 FOCUS","ZERO CRASH","XP BOOST"],"description":"Neon green and black esports advertisement with blurred-face male gamer holding a tall can labeled XP BOOST, RGB computer setup, lightning graphics, hex icons, and energetic gaming typography."},{"position":"bottom far right","type":"food comparison chart infographic","visible_text_count":18,"texts":["Enjoy the Delight, There''s More Than Meets the Eye.","Seafood and Fish","Meat Lovers","Roasted Salmon","1. Marinate salmon slices","2. Place salmon in the air fryer","3. Set to 180 degrees for 15 minutes","Crispy Texture, Tender and Not Greasy","Oil-Free Roast Chicken","1. Marinate a 2-pound chicken","2. Place the whole chicken in the air fryer","3. Set to 200 degrees for 45 minutes","Oil-Free and Fat-Free Healthy Eating"],"description":"Clean white and orange culinary infographic comparing salmon and roast chicken for air fryer cooking, with overhead plated food photos, ingredient bowls, utensils, small process thumbnails, and tidy recipe cards."}]},"quality_notes":"Make the collage feel like a screenshot from a model capability tweet: varied aspect ratios inside the grid, some cropped edges, high prompt adherence, crisp readable text, realistic product photography mixed with polished infographic design. Faces in human panels should be intentionally blurred or anonymized. Use saturated commercial colors, sharp UI overlays, and dense small typography.","customization":{"main Chinese headline":"{argument name=\"main Chinese headline\" default=\"国风产品也能用AI修出高级感\"}","livestream sale price":"{argument name=\"livestream sale price\" default=\"¥199\"}","wellbeing title":"{argument name=\"wellbeing title\" default=\"Habits for Emotional Wellbeing\"}","game character name":"{argument name=\"game character name\" default=\"Stella\"}","gaming product name":"{argument name=\"gaming product name\" default=\"XP BOOST\"}"}}', 'Generates a dense 3x3 showcase collage of varied AI-created ads, infographics, UI screens, recipes, and product layouts for model capability demonstrations.。来自 YouMind-OpenLab GPT-Image-2 案例库。', 'Infographic / Edu Visual - AI Ad and Infographic Capability Collage Generates a dense 3x3 showcase collage of varied AI-created ads, infographics, UI screens, recipes, and product layouts for model capability demonstrations.。来自 YouMind-OpenLab GPT-Image-2 案例库。 {"type":"dense comparison collage of AI-generated commercial prompt-adherence examples","format":"single 3x3 social media showcase grid, 16:9 aspect ratio, no gutters or thin seams between panels, high-detail realistic and graphic mixed media","overall_style":"A busy viral tech-demo collage showing that one image model can generate Chinese ads, livestream shopping layouts, English infographics, game UI, food recipe posters, product photography, and handwritten mail. Preserve readable typography where possible, mixing Chinese and English text, with realistic lighting, ecommerce overlays, icons, badges, and small UI details.","layout":{"count":9,"arrangement":"three rows by three columns, with the center and right panels tightly cropped like a screenshot mosaic","panels":[{"position":"top left","type":"Chinese tea product beautification ad","visible_text_count":8,"texts":["国风产品也能用AI修出高级感","茶叶、礼盒、伴手礼都能套用","Before","After","教程干货","#AI修图","#国风品牌","#产品美化","#电商教程"],"description":"Traditional Chinese tea still-life with cylindrical green tea tins, loose tea leaves, ceramic cups, wooden table, warm dark studio lighting; a Before/After split shows the same tea product transformed into an elegant ink-wash landscape background with bamboo and mountains."},{"position":"top center","type":"Chinese livestream flash sale screenshot","visible_text_count":13,"texts":["LIVE","12.8万人","88.6K","FLASH SALE","闪购!","时光焕亮修护精华液","¥199","¥399","仅剩12件","分享","送礼","立即抢购","VIP"],"description":"A female beauty influencer with blurred face holds a cosmetic serum bottle and points upward, surrounded by livestream hearts, viewer counters, chat bubbles, red sale badge, price card, and mobile shopping interface elements."},{"position":"top right","type":"decorative English wellbeing infographic","visible_text_count":7,"texts":["Habits for Emotional Wellbeing","Practice Mindfulness","Be present, observe without judging, accept without resisting","Continuous Learning","Cultivate Gratitude","Regular Physical Activity","Stay Connected","Prioritize Sleep"],"description":"Cream parchment-style infographic with navy blue and gold botanical ornaments, symmetrical leaves, small line icons, curved dividers, and serif typography about mental health habits."},{"position":"bottom left","type":"Chinese kitchen appliance ecommerce poster","visible_text_count":13,"texts":["森火 SENFO","森焙嵌入式蒸烤箱","把星级餐桌搬回家","蒸 | 烤 | 空气炸 | 发酵 | 炖煮 五合一","70L大容量","上下独立控温","智能菜单","一键清洁","¥5699","前200名","赠豪华烘焙套装","限时钜惠","马上升级厨房"],"description":"Modern minimalist kitchen interior with built-in black glass oven, island counter, sea-view window, vertical white feature-card sidebar with appliance icons and pricing."},{"position":"bottom center left","type":"Chinese spicy pork recipe poster","visible_text_count":10,"texts":["辣椒炒肉","越简单越考验火候","家庭灶也能炒出餐馆效果","食材:","五花肉 260g","二荆条 120g","薄皮青椒 100g","独蒜 1头","Step 1 切肉","Step 2 腌制","Step 3 干煸辣椒","Step 4 猪肉入锅","Step 5 蒜末、辣椒回锅","锅气是灵魂"],"description":"Dark smoky food poster with a wok or black pan full of glossy pork belly slices and green chilies, steam rising, bold Chinese headline and numbered cooking steps with small ingredient icons."},{"position":"bottom center","type":"fantasy mobile game gacha UI screenshot","visible_text_count":15,"texts":["BLIND BOX","COLLECTION","WISH LIST","EVENT","RANKING","Stella","Open 1 Box","Open 10 Boxes","NEW Starfall Series","Rate UP!","Collect Reward","45/100","HOME","SHOP","ADVENTURE","FRIENDS","MISSIONS"],"description":"Colorful purple-blue mobile game interface with a cute chibi cat-eared magical girl named Stella in the middle, bubbles, stars, currency counters across the top, side menu buttons, reward banners, and bottom navigation."},{"position":"bottom center right","type":"handwritten postcard and envelope","visible_text_count":8,"texts":["Dear Emily,","Paris is as lovely as we dreamed, with charming little bakeries and cafés lining every street. Yesterday, we visited the Louvre and spent hours marveling at the paintings. Missing you greatly and hoping you can join me here one day soon. Warmest wishes, Clara","PLACE STAMP HERE","Miss Emily Carter","28 Rosewood Avenue","Bath","Somerset","BA2 3JV","England"],"description":"Vintage beige postcard on wooden table, left side filled with cursive handwritten letter, right side with address lines, stamp placeholder, faint postal marks, warm nostalgic lighting."},{"position":"bottom right center","type":"gaming hydration drink ad","visible_text_count":11,"texts":["QUEUE UP.","POWER ON.","GAMING HYDRATION DRINK","ZERO CRASH FORMULA","Caffeine + electrolytes + B12, crafted for ranked nights and tournament weekends.","LEVEL UP YOUR FOCUS","CLEAN ENERGY","ELECTROLYTE HYDRATION","B12 FOCUS","ZERO CRASH","XP BOOST"],"description":"Neon gre